  Theorem WFQ_pop :
       WFQ st' XC XB
    /\ (forall b, In b (l2 ++ T) -> In (qb_addr b) (map qb_addr gl))
    /\ Forall (batch_ok st) l2 /\ Forall (fun b => batch_ok st b \/ xbatch st b) T
    /\ b2 = bsum l2 /\ b2 <= min_size
